oxy_webhelp_navlinks = {"mongodb_legal_hold_snapshots-d39536e37088":{"topics":[{"title":"Placing a MongoDB snapshot on legal hold","shortdesc":"<p class=\"shortdesc\">Placing a legal hold on a MongoDB snapshot indefinitely retains that snapshot         regardless of the assigned SLA Domain retention policy. <span class=\"ph\">RSC<\/span> supports legal         hold for MongoDB snapshots from Rubrik CDM version 9.6 and later.<\/p>","href":"mongodb\/mongodb_placing_snapshots_legal_hold.html","attributes":{"data-id":"mongodb_placing_snapshots_legal_hold"},"menu":{"hasChildren":false},"tocID":"mongodb_placing_snapshots_legal_hold-d39536e37099","topics":[]},{"title":"Removing legal hold from MongoDB snapshots","shortdesc":"<p class=\"shortdesc\">Remove legal hold from a MongoDB snapshot to return the snapshot to normal retention         management. <span class=\"ph\">RSC<\/span> supports legal hold for MongoDB snapshots from Rubrik CDM         version 9.6 and later.<\/p>","href":"mongodb\/mongodb_removing_legal_hold_snapshots.html","attributes":{"data-id":"mongodb_removing_legal_hold_snapshots"},"menu":{"hasChildren":false},"tocID":"mongodb_removing_legal_hold_snapshots-d39536e37113","topics":[]}]}};